  if (!url) {
    console.log('[telemetry] boot', payload);
    return;
  }

  fetch(url, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(payload),
  }).catch((err) => console.warn('[telemetry] send failed:', err.message));
}

